def kmp_table(w):
    T = [0] * len(w)
    pos = 1
    cnd = 0
    while pos < len(w):
        if w[pos] == w[cnd]:
            T[pos] = cnd + 1
            pos += 1
            cnd += 1
        elif cnd > 0:
            cnd = T[cnd-1]
        else:
            pos += 1
    return T

def kmp_search(s, w):
    T = kmp_table(w)
    m = 0
    i = 0
    while m + i < len(s):
