                return -1; // Қалаларды қосу мүмкін емес
            }

            cost += minEdge;
            union(parent, u, v);
            edgesUsed++;
        }

        return cost;
    }

    private static int find(int[] parent, int i) {
        if (parent[i] == i) {
            return i;
        }
        return parent[i] = find(parent, parent[i]);
    }

    private static void union(int[] parent, int i, int j) {
        int rootI = find(parent, i);
        int rootJ = find(parent, j);
        parent[rootI] = rootJ;
    }

    public static void main(String[] args) {
        int[][] roads = {{1,2,1},{1,3,4},{1,4,2},{2,3,3},{2,4,2},{3,4,1}};
        int result = minCostToConnectCities(roads);
        System.out.println("Мінімум құны: " + result);
    }
}
```

