```java
import java.security.MessageDigest;
import java.io.FileInputStream;
import java.io.IOException;

public class MD5Checksum {
    public static void main(String[] args) throws IOException {
        try {
            byte[] fileContent = loadFileContent("your_file.txt");
            String md5Checksum = calculateMD5(fileContent);
            System.out.println("MD5 checksum: " + md5Checksum);
        } catch (IOException e) {
            System.err.println("Error: " + e.getMessage());
        }
    }

    public static byte[] loadFileContent(String filename) throws IOException {
        FileInputStream fis = new FileInputStream(filename);
        byte[] fileContent = new byte[(int) fis.available()];
        fis.read(fileContent);
        fis.close();
        return fileContent;
    }

    public static String calculateMD5(byte[] fileContent) {
        MessageDigest md = MessageDigest.getInstance("MD5");
        md.update(fileContent);
        byte[] digest = md.digest();
        return java.util.Arrays.toString(digest);
    }
}
```

