            // Байттарды шестрингеге түрлендіру
            StringBuilder sb = new StringBuilder();
            for (byte b : md5Bytes) {
                sb.append(String.format("%02x", b));
            }

            return sb.toString();

        } catch (Exception e) {
            e.printStackTrace();
            return null; // Егер орындауға қатысты мәселе болса, null қайтарады
